using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using System.Text;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Collections.Generic;
namespace Overclock {
 static class StudioTests {
  static void Assert(bool b,string message){if(!b)throw new Exception(message);}
  static void Reject(Action action){bool rejected=false;try{action();}catch{rejected=true;}Assert(rejected,"Invalid studio data accepted");}
  static void Text(BinaryWriter w,string text){byte[] b=Encoding.UTF8.GetBytes(text+"\0");w.Write((ushort)b.Length);w.Write(b);}
  static byte[] DevicePacket(bool reversed=false){using(var m=new MemoryStream()){using(var w=new BinaryWriter(m,Encoding.UTF8,true)){w.Write(0u);w.Write(0);foreach(string s in new[]{"RGB fixture only","Test vendor","Fixture - not hardware","1","serial-123","usb-fixture"})Text(w,s);w.Write((ushort)1);w.Write(0);Text(w,"Static");w.Write(7);w.Write(81u);w.Write(reversed?4u:1u);w.Write(reversed?0u:10u);w.Write(20u);w.Write(100u);w.Write(1u);w.Write(1u);w.Write(reversed?2u:5u);w.Write(60u);w.Write(0u);w.Write(2u);w.Write((ushort)1);w.Write(0x004417ffu);w.Write((ushort)1);Text(w,"Zone A");w.Write(0u);w.Write(1u);w.Write(1u);w.Write(1u);w.Write((ushort)0);w.Write((ushort)1);Text(w,"LED A");w.Write(0u);w.Write((ushort)1);w.Write(0x004417ffu);}byte[] data=m.ToArray();Array.Copy(BitConverter.GetBytes((uint)data.Length),data,4);return data;}}
  static byte[] Read(NetworkStream s,int n){byte[] b=new byte[n];int p=0;while(p<n){int got=s.Read(b,p,n-p);if(got==0)throw new EndOfStreamException();p+=got;}return b;}
  static void OfflineFixture(int scenario){var server=new TcpListener(IPAddress.Loopback,0);server.Start();int port=((IPEndPoint)server.LocalEndpoint).Port;var task=Task.Run(()=>{try{using(var c=server.AcceptTcpClient())using(var stream=c.GetStream()){stream.ReadTimeout=5000;while(true){byte[] h;try{h=Read(stream,16);}catch(EndOfStreamException){break;}uint id=BitConverter.ToUInt32(h,8);Read(stream,(int)BitConverter.ToUInt32(h,12));if(id==50)continue;if(scenario==2)break;byte[] payload=BitConverter.GetBytes(id==40?3u:0u);using(var w=new BinaryWriter(stream,Encoding.UTF8,true)){w.Write(Encoding.ASCII.GetBytes(scenario==1?"BAD!":"ORGB"));w.Write(0u);w.Write(id);w.Write((uint)payload.Length);w.Write(payload);w.Flush();}if(scenario==1)break;}}}finally{server.Stop();}});using(var provider=new OpenRgbStudio(port)){if(scenario==0)Assert(provider.Execute(new StudioCommand(),CancellationToken.None).GetAwaiter().GetResult().Devices.Count==0,"No-device state failed");else Reject(()=>provider.Execute(new StudioCommand(),CancellationToken.None).GetAwaiter().GetResult());}Assert(task.Wait(6000),"Offline fixture did not finish");task.GetAwaiter().GetResult();}
  static string ProtocolFixtures(){byte[] data=DevicePacket();var reversed=OpenRgbStudio.Parse(DevicePacket(true),0);Assert(reversed.Modes[0].SpeedMin==4&&reversed.Modes[0].SpeedMax==0&&OpenRgbStudio.Normalize(2,4,0)==50&&OpenRgbStudio.Raw(100,4,0)==0&&OpenRgbStudio.Raw(0,4,0)==4,"Reversed RGB speed range regression");var device=OpenRgbStudio.Parse(data,0);Assert(device.Modes.Count==1&&device.Zones.Count==1&&device.Colors[0]==0x004417ffu&&!device.Ambiguous,"Valid SDK v3 fixture parsing");for(int i=0;i<data.Length;i+=7){int length=i;Reject(()=>OpenRgbStudio.Parse(new ArraySegment<byte>(data,0,length).ToArray(),0));}
   var server=new TcpListener(IPAddress.Loopback,0);server.Start();int port=((IPEndPoint)server.LocalEndpoint).Port;var packets=new List<uint>();byte[] update=null;
   var task=Task.Run(()=>{try{using(var client=server.AcceptTcpClient())using(var stream=client.GetStream()){stream.ReadTimeout=5000;while(true){byte[] h;try{h=Read(stream,16);}catch(EndOfStreamException){break;}uint id=BitConverter.ToUInt32(h,8),dev=BitConverter.ToUInt32(h,4),size=BitConverter.ToUInt32(h,12);Assert(size<100000,"Fixture received oversized command");byte[] payload=Read(stream,(int)size);packets.Add(id);if(id==1101){update=payload;continue;}byte[] response=id==40?BitConverter.GetBytes(5u):id==0?BitConverter.GetBytes(1u):id==1?data:null;if(response==null)continue;using(var w=new BinaryWriter(stream,Encoding.UTF8,true)){w.Write(Encoding.ASCII.GetBytes("ORGB"));w.Write(dev);w.Write(id);w.Write((uint)response.Length);w.Write(response);w.Flush();}}}}finally{server.Stop();}});
   using(var provider=new OpenRgbStudio(port)){var reply=provider.Execute(new StudioCommand(),CancellationToken.None).GetAwaiter().GetResult();Assert(reply.Devices.Count==1,"Mock inventory");var d=reply.Devices[0];provider.Execute(new StudioCommand{Action="apply",Id=d.Id,Mode="Static",Hex="#112233",Brightness=50,Speed=100},CancellationToken.None).GetAwaiter().GetResult();Assert(update!=null&&BitConverter.ToUInt32(update,0)==update.Length&&BitConverter.ToUInt32(update,update.Length-4)==0x00332211,"UpdateMode encoding or RGB endianness");provider.Execute(new StudioCommand{Action="restore",Id=d.Id,Snapshot=d},CancellationToken.None).GetAwaiter().GetResult();Assert(BitConverter.ToUInt32(update,update.Length-4)==0x004417ffu,"Restore mode colours");}
   Assert(task.Wait(7000),"Mock SDK did not stop");task.GetAwaiter().GetResult();Assert(packets.Contains(40)&&packets.Contains(1101),"Protocol negotiation or apply missing");
   // A loopback peer reporting protocol 2 must be rejected before inventory or writes.
   var incompatible=new TcpListener(IPAddress.Loopback,0);incompatible.Start();int oldPort=((IPEndPoint)incompatible.LocalEndpoint).Port;var oldTask=Task.Run(()=>{using(var c=incompatible.AcceptTcpClient())using(var s=c.GetStream()){byte[] h=Read(s,16);Read(s,(int)BitConverter.ToUInt32(h,12));using(var w=new BinaryWriter(s)){w.Write(Encoding.ASCII.GetBytes("ORGB"));w.Write(0u);w.Write(40u);w.Write(4u);w.Write(2u);}}incompatible.Stop();});using(var provider=new OpenRgbStudio(oldPort))Reject(()=>provider.Execute(new StudioCommand(),CancellationToken.None).GetAwaiter().GetResult());Assert(oldTask.Wait(5000),"Incompatible fixture did not stop");
   OfflineFixture(0);OfflineFixture(1);OfflineFixture(2);
   return "PASS mock loopback OpenRGB: negotiated v3 data on v5 server, actual inventory/modes/zones/LED parsing, truncation boundaries, Apply packet sizing/colour encoding, Restore packet, incompatible protocol, no devices, bad signature and disconnect rejection. Mock only; no real RGB hardware.";
  }
  public static string Run(string folder){
   using(var box=new StudioCheckBox{Width=470,Height=44,Text="Enable HDR - HDR not supported",Enabled=false,BackColor=Theme.Background,Font=Theme.Face(11)})using(var image=new System.Drawing.Bitmap(470,44)){box.DrawToBitmap(image,new System.Drawing.Rectangle(0,0,470,44));image.Save(Path.Combine(folder,"hdr-disabled-checkbox-fixture.png"));}
   var hdr=new StudioDevice();HdrDisplay.Decode(hdr,65,1);Assert(!hdr.HdrSupported&&!hdr.HdrCanToggle,"SDR wide-colour was mistaken for HDR");HdrDisplay.Decode(hdr,17,0);Assert(hdr.HdrSupported&&hdr.HdrCanToggle&&hdr.HdrEnabled==false,"HDR-capable disabled state");HdrDisplay.Decode(hdr,51,2);Assert(hdr.HdrEnabled==true&&hdr.HdrActive&&hdr.HdrCanToggle,"HDR enabled state");HdrDisplay.Decode(hdr,25,0);Assert(!hdr.HdrCanToggle,"HDR policy restriction ignored");
   Assert(NativeDisplayStudio.Normalize(60,20,100)==50&&NativeDisplayStudio.Raw(50,20,100)==60,"Monitor range mapping");Reject(()=>NativeDisplayStudio.Normalize(0,0,0));Reject(()=>NativeDisplayStudio.Raw(101,0,100));Reject(()=>NativeDisplayStudio.Normalize(101,0,100));
   var p=new StudioProfile{Name="Fixture only",Kind="Display",Targets=new System.Collections.Generic.List<StudioCommand>{new StudioCommand{Action="apply",Id="fixture-monitor",Brightness=50}}};string file=Path.Combine(folder,"studio-profile-fixture.json");StudioProfiles.Save(p,file);Assert(StudioProfiles.Load(file).Targets[0].Brightness==50,"Profile roundtrip");p.Targets[0].Brightness=150;Reject(()=>StudioProfiles.Save(p,file));Assert(StudioProfiles.Load(file).Targets[0].Brightness==50,"Invalid save damaged previous profile");p.Targets[0].Brightness=0;p.Version=999;Reject(()=>StudioProfiles.Validate(p));Reject(()=>OpenRgbStudio.Parse(new byte[4],0));Reject(()=>OpenRgbStudio.Parse(new byte[]{255,255,255,127},0));Reject(()=>StudioJson.Parse<StudioProfile>("{bad"));
   using(var queue=new StudioQueue()){int active=0,max=0;var first=queue.Run(async token=>{active++;max=Math.Max(max,active);await Task.Delay(50).ConfigureAwait(false);active--;return 1;},CancellationToken.None);var second=queue.Run(async token=>{active++;max=Math.Max(max,active);await Task.Delay(10).ConfigureAwait(false);active--;return 2;},CancellationToken.None);Task.WaitAll(first,second);Assert(max==1,"Provider operations overlapped");using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();Reject(()=>queue.Run(t=>Task.FromResult(1),cancelled.Token).GetAwaiter().GetResult());}}
   using(var queue=new StudioQueue()){var release=new TaskCompletionSource<int>();var pending=new List<Task<int>>();for(int i=0;i<8;i++)pending.Add(queue.Run(t=>release.Task,CancellationToken.None));Reject(()=>queue.Run(t=>Task.FromResult(0),CancellationToken.None).GetAwaiter().GetResult());release.SetResult(1);Task.WaitAll(pending.ToArray());}
   var watch=System.Diagnostics.Stopwatch.StartNew();using(var host=new DisplayStudioClient("--worker delay-test "+Workers.Quote(Path.Combine(folder,"studio-hung-helper-fixture.txt")),350))Reject(()=>host.Execute(new StudioCommand(),CancellationToken.None).GetAwaiter().GetResult());Assert(watch.Elapsed.TotalSeconds<5,"Hung display helper was not bounded");
   return "PASS studios: monitor range boundaries, invalid ranges, atomic profile roundtrip, rejected invalid/versioned JSON, malformed/truncated SDK packets, serialized mailbox and cancellation (fixtures only; no hardware writes).\r\n"+ProtocolFixtures();
  }
 }
